export async function createScene(engine, canvas, BABYLON) {
  var scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.97, 0.93, 0.93);

  const camera = new BABYLON.ArcRotateCamera("camera", -Math.PI / 2, Math.PI / 2, 20, BABYLON.Vector3.Zero(), scene);
  camera.lowerAlphaLimit = -2.04;
  camera.upperAlphaLimit = -1.1;
  camera.lowerBetaLimit = 1.099;
  camera.upperBetaLimit = 2.229;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light1", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.7;

  const textureResolution = 1024;
  const dynamicTexture = new BABYLON.DynamicTexture("dynamicTexture", textureResolution, scene, true);
  const color = new BABYLON.Color3(0.26, 0.27, 0.6).toHexString();
  dynamicTexture.drawText("UNIT", 10, 300, "bold 180px Arial", color, "transparent", true);

  const textMaterial = new BABYLON.StandardMaterial("textMaterial", scene);
  textMaterial.diffuseTexture = dynamicTexture;
  textMaterial.emissiveColor = BABYLON.Color3.Black();
  textMaterial.diffuseTexture.hasAlpha = true;

  const textPlane = BABYLON.MeshBuilder.CreatePlane("textPlane", { width: 10, height: 10 }, scene);
  textPlane.scaling = new BABYLON.Vector3(10, 10, 10);
  textPlane.position = new BABYLON.Vector3(30, -25, 30);
  textPlane.material = textMaterial;

  const glassMesh = BABYLON.MeshBuilder.CreateTorusKnot(
    "torusKnot",
    {
      radius: 4.0,
      tube: 0.8,
      radialSegments: 128,
      tubularSegments: 64,
      p: 2,
      q: 3,
    },
    scene
  );

  const glassMesh2 = BABYLON.MeshBuilder.CreateBox("box", { size: 8 }, scene);
  glassMesh2.visibility = 0;

  glassMesh.onBeforeRenderObservable.add(() => {
    const deltaTime = scene.getEngine().getDeltaTime() * 0.001;
    const degreesPerSecond = -15;

    const time = performance.now() * 0.0005;
    const t = (Math.sin(time) + 1) / 2;

    const radiansPerSecond = degreesPerSecond * (Math.PI / 180);
    glassMesh.rotation.y += radiansPerSecond * deltaTime;
    glassMesh.rotation.x += radiansPerSecond * 0.01;

    glassMesh2.rotation.y += radiansPerSecond * deltaTime;
    glassMesh2.rotation.x += radiansPerSecond * 0.01;

    glassMesh.visibility = 1 - t;
    glassMesh2.visibility = t;
  });

  const glassMaterial = new BABYLON.PBRMaterial("glassMaterial", scene);
  glassMaterial.albedoColor = new BABYLON.Color3(0.89, 0.96, 0.97);
  glassMaterial.metallic = 0.1;

  glassMaterial.subSurface.tintColorAtDistance = 10;
  glassMaterial.subSurface.volumeIndexOfRefraction = 2;
  glassMaterial.subSurface.dispersion = 5;

  glassMaterial.backFaceCulling = true;
  glassMaterial.subSurface.minimumThickness = 0;
  glassMaterial.subSurface.maximumThickness = 2.26;
  glassMaterial.subSurface.useGltfStyleTextures = true;
  glassMaterial.subSurface.isRefractionEnabled = true;
  glassMaterial.enableSpecularAntiAliasing = true;
  glassMaterial.subSurface.volumeIndexOfRefraction = 1.75;
  glassMaterial.subSurface.isDispersionEnabled = true;
  glassMaterial.subSurface.useAlbedoToTintRefraction = true;
  glassMaterial.enableSpecularAntiAliasing = true;
  glassMaterial.subSurface.useGltfStyleTextures = true;
  glassMaterial.subSurface.useThicknessAsDepth = true;

  const refractionTexture = new BABYLON.RenderTargetTexture("opaqueRTT", 4096, scene, false, true);
  refractionTexture.renderList.push(textPlane);

  glassMaterial.refractionTexture = refractionTexture;

  glassMesh.material = glassMaterial;
  glassMesh2.material = glassMaterial;

  const dpp = new BABYLON.DefaultRenderingPipeline("dpp", true, scene);
  dpp.fxaaEnabled = true;
  dpp.samples = 4;
  dpp.imageProcessingEnabled = false;
  dpp.glowLayerEnabled = true;

  var taa = new BABYLON.TAARenderingPipeline("taa", scene);
  taa.disableOnCameraMove = false;
  taa.factor = 0.3;
  taa.msaaSamples = 8;
  taa.samples = 32;

  var mb = new BABYLON.MotionBlurPostProcess("mb", scene, 1.0, camera);

  return scene;
}
